// src/screens/LoginScreen.jsx
// SAME UI as original. Supabase auth → Django REST /api/auth/login/

import { useState, useEffect } from "react";
import { loginUser } from "../services/authService";
import { getCurrentUser } from "../services/authService";
import { loginBg, fbIcon, gmailIcon } from "../assets/images";
import { useAuth } from "../context/AuthContext";

export default function LoginScreen({ onNavigate, prefillPhone }) {
  const { setUser } = useAuth();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading]   = useState(false);
  const [error, setError]       = useState("");

  useEffect(() => {
    if (prefillPhone) setUsername(prefillPhone);
  }, [prefillPhone]);

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    if (!username.trim() || !password.trim()) {
      setError("Please fill in all fields.");
      return;
    }

    setLoading(true);
    // POST /api/auth/login/ — saves JWT tokens to localStorage
    const { error: loginError } = await loginUser(username.trim(), password);
    if (loginError) {
      setError(loginError);
      setLoading(false);
      return;
    }

    // Fetch user profile and store in context
    const { data: userData, error: userError } = await getCurrentUser();
    if (userError) {
      setError("Login succeeded but could not load user profile.");
      setLoading(false);
      return;
    }

    setUser(userData);
    setLoading(false);
    onNavigate("home"); // same as original
  };

  return (
    <div
      className="auth-root"
      style={{ backgroundImage: `url(${loginBg})`, backgroundSize: "cover", backgroundPosition: "center top" }}
    >
      <div className="auth-card">
        <div className="auth-logo">
          <div className="auth-logo-icon">🌾</div>
          <div className="auth-logo-text">Scare<span>Crow</span></div>
        </div>

        <h1 className="auth-title">LOG IN NOW</h1>
        <p className="auth-subtitle">
          Please log in to your account to continue using our app
        </p>

        <form onSubmit={handleLogin}>
          <div className="form-group">
            <label className="form-label">Username</label>
            <input
              className="form-input"
              type="text"
              placeholder="Username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              disabled={loading}
            />
          </div>

          <div className="form-group">
            <label className="form-label">Password</label>
            <input
              className="form-input"
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              disabled={loading}
            />
          </div>

          {error && (
  <div className="error-box" style={{ 
    animation: "none",
    opacity: 1 
  }}>
    {error}
  </div>
)}

          <button className="btn-primary" type="submit" disabled={loading}>
            {loading ? "Logging in…" : "LOG IN"}
          </button>
        </form>

        <div className="auth-footer-link">
          Don't have an account?{" "}
          <button onClick={() => onNavigate("signup")}>Sign Up</button>
        </div>

        <div className="social-section">
          <p className="social-divider">or continue with</p>
          <div className="social-buttons">
            <button className="social-btn" onClick={() => alert("Facebook login coming soon!")}>
              <img src={fbIcon} alt="Facebook" />
            </button>
            <button className="social-btn" onClick={() => alert("Google login coming soon!")}>
              <img src={gmailIcon} alt="Google" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
